package com.inventario.controller;
import com.inventario.domain.Cliente; import com.inventario.dto.Dtos.*; import com.inventario.service.ClienteService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/clientes") @CrossOrigin
public class ClienteController { private final ClienteService service; public ClienteController(ClienteService service){this.service=service;} @GetMapping public List<Cliente> listar(){return service.listar();} @PostMapping public Cliente crear(@RequestBody ClienteRequest r){return service.crear(r);} @PutMapping("/{id}") public Cliente actualizar(@PathVariable Long id,@RequestBody ClienteRequest r){return service.actualizar(id,r);} @DeleteMapping("/{id}") public void eliminar(@PathVariable Long id){service.eliminar(id);} }
